import{sitemap}from"./sitemap.min.js";function document(body){var e=globalThis.filePath.replace(/^.+?cruzgodar\.github\.io/,""),e=e.slice(0,e.lastIndexOf("/"));if(sitemap[e])return`<header>
	<div id="logo">
		<a href="/home" tabindex="-1">
			<img src="/graphics/general-icons/logo.webp" alt="Logo" tabindex="1" />
		</a>
	</div>
	
	<div style="height: 20px"></div>
	
	<h1 class="heading-text">${sitemap[e].title}</h1>
</header>

<main>
${body}
</main>`;throw new Error(e+" is not in sitemap!")}function bannerDocument(body){return`<div id="banner">
	<div id="banner-small"></div>
	<div id="banner-large"></div>
</div>

<div id="content-container">
	<div id="content">
		${document(body)}
	</div>
</div>`}function unorderedList(...items){return`<ul>${items.map(item=>`<li class="body-text">${item}</li>`).join("")}</ul>`}function orderedList(...items){return`<ol>${items.map(item=>`<li class="body-text">${item}</li>`).join("")}</ol>`}function heading(body,headingNumber){if("1"===headingNumber)return`<h1 class="heading-text">${body}</h1>`;if("2"===headingNumber)return`<h2 class="section-text">${body}</h2>`;throw new Error("Trying to use heading level >= 3")}function paragraph(body){return`<p class="body-text">${body}</p>`}function text(body){return body.replaceAll(/(\s)"(\S)/g,(match,$1,$2)=>$1+"&#x201C;"+$2).replaceAll(/^"(\S)/g,(match,$1)=>"&#x201C;"+$1).replaceAll(/"/g,"&#x201D;").replaceAll(/(\s)'(\S)/g,(match,$1,$2)=>$1+"&#x2018;"+$2).replaceAll(/^'(\S)/g,(match,$1)=>"&#x2018;"+$1).replaceAll(/'/g,"&#x2019;").replaceAll(/---/g,"&mdash;").replaceAll(/--/g,"&ndash;")}function carousel(...blocks){return`
		<div class="carousel">
			<div class="carousel-content">
				${blocks.map(block=>`<div class="carousel-entry">${block}</div>`).join("")}
			</div>

			<div class="carousel-dots">
				${'<div class="carousel-dot"><div class="fill"></div></div>'.repeat(blocks.length)}
			</div>
		</div>
	`}function clickTap(clickText,tapText){return`<span class="click-tap"><span>${clickText}</span><span>${tapText}</span></span>`}function galleryBlock(...data){if(data.length%2!=0)throw new Error("Invalid number of arguments");let e='<div class="gallery-block">';for(let t=0;t<data.length;t+=2){var a=data[t],i=data[t+1];e+=`
		<div class="gallery-image-${i}-${i}">
			<img src="/graphics/general-icons/placeholder.png" data-src="/gallery/thumbnails/${a}.webp" data-image-id="${a}" />
		</div>`}return e+"</div>"}function imageLinks(data){return`<div style="display: flex; justify-content: center; width: 100%;">
	<div class="image-links">${data.map(item=>{var e=resolveUrl((item="string"==typeof item?{url:item}:item).url),a=e.split(".")[0].split("/"),a=a[a.length-1];if(void 0===data.name&&void 0===sitemap[e])throw new Error(e+" is not in sitemap!");var i,t=data.name??sitemap[e].title;return item.forCard?`
				<a href="${i=e.slice(0,e.lastIndexOf("/"))}/?card=${a}" data-card-id="${a}" class="image-link">
					<img src="/graphics/general-icons/placeholder.png" data-src="${item.coverPath??i+`/cards/${a}/cover.webp`}" alt="${t}" tabindex="1" />
					
					<p class="image-link-subtext">${t}</p>
				</a>
			`:(i=e.includes(".")?e.slice(0,e.lastIndexOf("/"))+"/cover.webp":e+"/cover.webp",`
		<a href="${e}"${item.inNewTab?' data-in-new-tab="1"':""} class="image-link">
			<img src="/graphics/general-icons/placeholder.png" data-src="${item.coverPath??i}" alt="${t}" tabindex="1" />
			
			<p class="image-link-subtext">${t}</p>
		</a>`)}).join("")}</div>
</div>`}function card(id,name,body){return name?`<div id="${id}-card" class="card"><h1 class="heading-text">${name}</h1>${body}</div>`:`<div id="${id}-card" class="card">${body}</div>`}function externalCard(id){return`<div id="${id}-card" class="card external-card"></div>`}function debug(body){return`<div class="DEBUG">${body}</div>`}function resolveUrl(url){var e=globalThis.filePath.replace(/^.+?cruzgodar\.github\.io/,""),e=e.slice(0,e.lastIndexOf("/"));return"/"===url[0]?url:e+"/"+url}export{document,bannerDocument,unorderedList,orderedList,heading,paragraph,text,carousel,clickTap,galleryBlock,imageLinks,card,externalCard,debug};